🫛 snappea checks P models.

Usage: snappea [output options] <command> [options]

Commands:
  check      Find bugs in a model: run its test cases over many schedules.
             Use after every model change.
  replay     Re-run a bug's .schedule file to debug it or confirm a fix
  tests      List test cases, e.g. to pick one for `check`
  observe    Check logs of a real system against the model's spec monitors.
             Use to test that an implementation matches the model.
  coverage   Merge coverage from several runs (CI shards, processes)
  guide      How to model a design and test code against it. Start here:
             `snappea guide`, then `snappea guide testing` or `snappea guide syntax`.
  version    Print the version

Typical loop:
  snappea check                       # check every test case
  snappea replay PCheckerOutput/tcFoo/bug.schedule -v   # debug a bug
  snappea check tcFoo                 # confirm the fix

Commands that read P sources take .pproj or .p files. Without any, they use the
*.pproj file in the current folder, or else the *.p files in it and its immediate
subfolders.

Output is text on a terminal or in CI, JSON otherwise (agents, scripts).
--format text|json, --json or SNAPPEA_FORMAT=text|json override it.
--json-report FILE also writes the JSON result to FILE.

Run `snappea <command> --help` for a command's options and examples.

command:
cd /work
cat > Names.p <<'EOF'
/* Unique usernames over a per-key load/CAS store. See DESIGN.md.
 * Keys: name record (owner or -1), user record (name or -1). No cross-key atomicity.
 * Users 0..1, names 0..1. kind 0 = register, 1 = rename.
 * Algorithm: claim new name by CAS on its name record, then CAS the user record,
 * then (rename only) release the old name record.
 */
type Op = (kind: int, name: int);
type Rec = (version: int, value: int);

event eLoad: (client: machine, isName: bool, key: int);
event eLoaded: Rec;
event eCas: (client: machine, isName: bool, key: int, version: int, value: int);
event eCasResult: bool;
event eDump: machine;
event eStart;
event eClientDone;
event eInvoked: (user: int, kind: int, name: int);
event eReturned: (user: int, kind: int, name: int, ok: bool);
event eFinalName: (user: int, name: int);
event eFinalOwner: (name: int, owner: int);
event eFinished;

// Independent oracle. Exact results are checked while calls never overlap;
// once calls overlap only user-local facts and the final state are checked.
spec NamesContract observes eInvoked, eReturned, eFinalName, eFinalOwner, eFinished {
  var held: map[int, int];
  var inflight: int;
  var exact: bool;
  var seen: int;

  fun heldBy(u: int): int {
    if (u in held) { return held[u]; }
    return -1;
  }
  fun free(n: int): bool {
    var u: int;
    foreach (u in keys(held)) { if (held[u] == n) { return false; } }
    return true;
  }
  fun expect(user: int, kind: int, name: int): bool {
    var cur: int;
    cur = heldBy(user);
    if (kind == 1 && cur == -1) { return false; }
    if (cur == name) { return true; }
