/* Unique usernames over a per-key load/CAS store. See DESIGN.md.
 * Records: name record (owner or -1), user record (name or -1). Only single-key
 * load and CAS are atomic. Users 0..1, names 0..1. kind 0 = register, 1 = rename.
 * Algorithm: claim the new name by CAS on its record, then set the user record,
 * then (rename only) release the old name record.
 */
type Rec = (version: int, value: int);

event eLoad: (client: machine, isName: bool, key: int);
event eLoaded: Rec;
event eCas: (client: machine, isName: bool, key: int, version: int, value: int);
event eCasResult: bool;
event eDump: machine;
event eNext;
event eClientDone;
event eInvoked: (user: int, kind: int, name: int);
event eReturned: (user: int, kind: int, name: int, ok: bool);
event eFinalName: (user: int, name: int);
event eFinalOwner: (name: int, owner: int);
event eFinished;

// Independent oracle. Results are checked exactly while calls never overlap;
// once calls overlap, only the final state (which must match what each user was
// told, and be a bijection) is checked.
spec NamesContract observes eInvoked, eReturned, eFinalName, eFinalOwner, eFinished {
  var held: map[int, int];
  var inflight: int;
  var overlapped: bool;
  var seen: int;

  fun heldBy(u: int): int {
    if (u in held) { return held[u]; }
    return -1;
  }
  fun holder(n: int): int {
    var u: int;
    var r: int;
    r = -1;
    foreach (u in keys(held)) { if (held[u] == n) { r = u; } }
    return r;
  }
  fun expect(user: int, kind: int, name: int): bool {
    var cur: int;
    cur = heldBy(user);
    if (kind == 1 && cur == -1) { return false; }
    if (cur == name) { return true; }
    if (kind == 0 && cur != -1) { return false; }
    return holder(name) == -1;
  }

  start hot state Running {
    on eInvoked do (p: (user: int, kind: int, name: int)) {
      inflight = inflight + 1;
      if (inflight > 1) { overlapped = true; }
    }
    on eReturned do (p: (user: int, kind: int, name: int, ok: bool)) {
      inflight = inflight - 1;
      if (!overlapped) {
        assert p.ok == expect(p.user, p.kind, p.name), "result disagrees with contract";
      }
      if (p.ok) { held[p.user] = p.name; }
    }
    on eFinalName do (p: (user: int, name: int)) {
      assert heldBy(p.user) == p.name, "name_of disagrees with successful calls";
      seen = seen + 1;
    }
    on eFinalOwner do (p: (name: int, owner: int)) {
      assert p.owner == holder(p.name), "owner disagrees with name_of";
      seen = seen + 1;
    }
    on eFinished do {
      assert seen == 4, "final state must be fully read";
      goto Complete;
    }
  }
  state Complete { }
}

// Atomic per-key primitives, like runtime.Store.
machine Store {
  var nameVer: map[int, int];
  var nameVal: map[int, int];
  var userVer: map[int, int];
  var userVal: map[int, int];
  start state Ready {
    entry {
      var i: int;
      while (i < 2) {
        nameVal[i] = -1; nameVer[i] = 0; userVal[i] = -1; userVer[i] = 0;
        i = i + 1;
      }
    }
    on eLoad do (p: (client: machine, isName: bool, key: int)) {
      if (p.isName) { send p.client, eLoaded, (version = nameVer[p.key], value = nameVal[p.key]); }
      else { send p.client, eLoaded, (version = userVer[p.key], value = userVal[p.key]); }
    }
    on eCas do (p: (client: machine, isName: bool, key: int, version: int, value: int)) {
      if (p.isName) {
        if (nameVer[p.key] == p.version) {
          nameVer[p.key] = p.version + 1; nameVal[p.key] = p.value;
          send p.client, eCasResult, true;
        } else { send p.client, eCasResult, false; }
      } else {
        if (userVer[p.key] == p.version) {
          userVer[p.key] = p.version + 1; userVal[p.key] = p.value;
          send p.client, eCasResult, true;
        } else { send p.client, eCasResult, false; }
      }
    }
    on eDump do (c: machine) {
      var i: int;
      while (i < 2) {
        announce eFinalName, (user = i, name = userVal[i]);
        announce eFinalOwner, (name = i, owner = nameVal[i]);
        i = i + 1;
      }
      announce eFinished;
    }
  }
}

machine Client {
  var store: Store;
  var coord: machine;
  var user: int;
  var ops: seq[(kind: int, name: int)];
  var rec: Rec;
  start state Idle {
    entry (input: (store: Store, coord: machine, user: int, ops: seq[(kind: int, name: int)])) {
      store = input.store; coord = input.coord; user = input.user; ops = input.ops;
    }
    on eNext goto Run;
  }
  state Run {
    entry {
      var i: int;
      var ok: bool;
      while (i < sizeof(ops)) {
        announce eInvoked, (user = user, kind = ops[i].kind, name = ops[i].name);
        if (ops[i].kind == 0) { ok = register(ops[i].name); }
        else { ok = rename(ops[i].name); }
        announce eReturned, (user = user, kind = ops[i].kind, name = ops[i].name, ok = ok);
        i = i + 1;
      }
      send coord, eClientDone;
    }
  }

  fun load(isName: bool, key: int) {
    send store, eLoad, (client = this, isName = isName, key = key);
    receive { case eLoaded: (r: Rec) { rec = r; } }
  }
  fun cas(isName: bool, key: int, version: int, value: int): bool {
    var res: bool;
    send store, eCas, (client = this, isName = isName, key = key, version = version, value = value);
    receive { case eCasResult: (b: bool) { res = b; } }
    return res;
  }
  // Take the name record for this user; false if someone else holds it.
  fun claim(name: int): bool {
    while (true) {
      load(true, name);
      if (rec.value == user) { return true; }
      if (rec.value != -1) { return false; }
      if (cas(true, name, rec.version, user)) { return true; }
    }
    return false;
  }
  fun setUser(name: int) {
    var done: bool;
    while (!done) {
      load(false, user);
      done = cas(false, user, rec.version, name);
    }
  }
  fun release(name: int) {
    var done: bool;
    while (!done) {
      load(true, name);
      if (rec.value != user) { done = true; }
      else { done = cas(true, name, rec.version, -1); }
    }
  }
  fun register(name: int): bool {
    var cur: int;
    load(false, user);
    cur = rec.value;
    if (cur == name) { return true; }
    if (cur != -1) { return false; }
    if (!claim(name)) { return false; }
    setUser(name);
    return true;
  }
  fun rename(name: int): bool {
    var cur: int;
    load(false, user);
    cur = rec.value;
    if (cur == -1) { return false; }
    if (cur == name) { return true; }
    if (!claim(name)) { return false; }
    setUser(name);
    release(cur);
    return true;
  }
}

// snappea: driver
machine Scenario {
  var clients: seq[Client];
  var sequential: bool;
  var store: Store;
  var done: int;
  var next: int;
  start state Running {
    entry (input: (sequential: bool, ops0: seq[(kind: int, name: int)], ops1: seq[(kind: int, name: int)])) {
      store = new Store();
      sequential = input.sequential;
      clients += (0, new Client((store = store, coord = this, user = 0, ops = input.ops0)));
      clients += (1, new Client((store = store, coord = this, user = 1, ops = input.ops1)));
      if (sequential) { send clients[0], eNext; }
      else { send clients[0], eNext; send clients[1], eNext; }
    }
    on eClientDone do {
      done = done + 1;
      if (sequential && done == 1) { send clients[1], eNext; }
      if (done == 2) { send store, eDump, this; }
    }
  }
}

fun mk(k0: int, n0: int, k1: int, n1: int): seq[(kind: int, name: int)] {
  var s: seq[(kind: int, name: int)];
  s += (0, (kind = k0, name = n0));
  s += (1, (kind = k1, name = n1));
  return s;
}

// Generated: both users run two ops of random kind and name, concurrently.
machine Generated {
  start state Init {
    entry {
      new Scenario((sequential = false,
        ops0 = mk(choose(2), choose(2), choose(2), choose(2)),
        ops1 = mk(choose(2), choose(2), choose(2), choose(2))));
    }
  }
}
// Same, one user at a time: exact results checked.
machine GeneratedSeq {
  start state Init {
    entry {
      new Scenario((sequential = true,
        ops0 = mk(choose(2), choose(2), choose(2), choose(2)),
        ops1 = mk(choose(2), choose(2), choose(2), choose(2))));
    }
  }
}
// Both register the same name, then try to rename to the other.
machine SameName {
  start state Init {
    entry { new Scenario((sequential = false, ops0 = mk(0, 0, 1, 1), ops1 = mk(0, 0, 1, 1))); }
  }
}
// Swap attempt: each holds a name, each renames to the other's.
machine Swap {
  start state Init {
    entry { new Scenario((sequential = false, ops0 = mk(0, 0, 1, 1), ops1 = mk(0, 1, 1, 0))); }
  }
}
// u0 moves off name 0 while u1 registers it.
machine Handoff {
  start state Init {
    entry { new Scenario((sequential = false, ops0 = mk(0, 0, 1, 1), ops1 = mk(1, 1, 0, 0))); }
  }
}

